style.css:
@-moz-document domain("calendar.google.com"), domain("www.google.com") {
/* ========== General Clean Look ========== */
  body {
    font-family: 'Segoe UI', sans-serif !important;
    background-color: #111 !important;
  }

  .VfPpkd-Bz112c-RLmnJb {
    background-color: #1c1c1c !important;
    color: #fff !important;
  }

  /* ========== Header Fix ========== */
  .gb_uc, .gb_3d, .gb_6d {
    background-color: #000 !important;
    color: #fff !important;
  }

  /* ========== Calendar Day / Week View BG ========== */
  .z0 {
    background-color: #161616 !important;
  }

  .tg .lv, .tg .lZ, .tg .mG, .tg .mH {
    border-color: #333 !important;
  }

  /* ========== Time Labels ========== */
  .tg-col-time {
    background-color: #111 !important;
    color: #aaa !important;
  }

  /* ========== 8-8-8 Block Highlighting ========== */
  /* Morning Work Block (6AM–2PM) */
  .tg-time-6am, .tg-time-7am, .tg-time-8am, .tg-time-9am, .tg-time-10am,
  .tg-time-11am, .tg-time-12pm, .tg-time-1pm {
    background-color: rgba(255, 0, 0, 0.1) !important;
  }

  /* Personal Life Block (2PM–10PM) */
  .tg-time-2pm, .tg-time-3pm, .tg-time-4pm, .tg-time-5pm, .tg-time-6pm,
  .tg-time-7pm, .tg-time-8pm, .tg-time-9pm {
    background-color: rgba(0, 255, 0, 0.08) !important;
  }

  /* Rest Block (10PM–6AM next day) */
  .tg-time-10pm, .tg-time-11pm, .tg-time-12am, .tg-time-1am, .tg-time-2am,
  .tg-time-3am, .tg-time-4am, .tg-time-5am {
    background-color: rgba(0, 136, 255, 0.08) !important;
  }

  /* ========== Event Cards ========== */
  .yn {
    border-radius: 10px !important;
    padding: 4px !important;
    box-shadow: 0 2px 5px rgba(0,0,0,0.3) !important;
  }

  /* ========== Hide Annoying Sidebars (Optional) ========== */
  .gb_gf, .gb_ie, .DShyMc-XxYAQc {
    display: none !important;
  }
}
